const p = $json.body ?? $json;
const transcript = String(p.transcript ?? p.content ?? '').trim();
if (!transcript) throw new Error('Falta la transcripción');
if (transcript.length > 20000) throw new Error('La transcripción supera 20 000 caracteres');
const title = String(p.title ?? p.subject ?? 'Reunión NEXORA').trim();
const parts = transcript.split(/\n|[.!?](?:\s+|$)/).map(x => x.trim()).filter(Boolean);
const decisions = parts.filter(x => /acordamos|decidimos|se aprueba|quedamos|decisión/i.test(x)).slice(0, 8);
const tasks = parts.filter(x => /debemos|hay que|encarg|responsable|entregar|preparar|revisar|terminar/i.test(x)).slice(0, 10).map((text, i) => { const direct = text.match(/^([A-ZÁÉÍÓÚÑ][\wÁÉÍÓÚÑáéíóúñ-]+)\s+(?:es\s+)?(?:responsable|encargad[oa])/); const labeled = text.match(/(?:responsable|encargad[oa]):?\s*([A-ZÁÉÍÓÚÑ][\wÁÉÍÓÚÑáéíóúñ-]+)/); return { id: i + 1, task: text, owner: direct?.[1] || labeled?.[1] || 'por asignar', status: 'pendiente' }; });
const risks = parts.filter(x => /riesgo|bloqueo|problema|falta|retraso|urgente/i.test(x)).slice(0, 6);
const attendees = Array.isArray(p.attendees) ? p.attendees : String(p.attendees ?? '').split(',').map(x => x.trim()).filter(Boolean);
return [{ json: { ok: true, workflow: 'laboratorio-reuniones', meetingId: `meet-${Date.now().toString(36)}`, title, date: String(p.date ?? new Date().toISOString()), attendees, summary: parts.slice(0, 4).join('. '), decisions: decisions.length ? decisions : ['No se detectaron decisiones explícitas'], tasks, risks, followUp: { recommended: tasks.length > 0, message: tasks.length ? `Dar seguimiento a ${tasks.length} tarea(s)` : 'Confirmar próximos pasos con el equipo' } } }];

const fs = require('fs');
const file = '/files/nexora-meetings.jsonl';
for (const item of items) fs.appendFileSync(file, `${JSON.stringify(item.json)}\n`, 'utf8');
return items.map(item => ({ json: { ...item.json, storedLocally: true, localFile: file, message: 'Acta inteligente creada con acuerdos, tareas y riesgos' } }));
